void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    // Normalize + Center + Fix aspect-ratio
    vec2 p = (fragCoord * 2. - iResolution.xy) / iResolution.y;

    float a = atan(p.y, p.x);
    float l = length(p);
    float i = sin(a+l*4. + iTime*.5) * sin(a+l*12. + iTime*.2);

    // Cosine palette
    vec3 color = cos(6.2831853 * (i + vec3(.1,.22,.35))) * .5 + .5;
    fragColor = vec4(color, 1.);
}
